'use client';

import type { ComponentProps } from 'react';
import { useDocsPage } from 'local:<dir>/docs/page/index.tsx';
import { cn } from 'local:utils/cn.ts';

export function Container(props: ComponentProps<'article'>) {
  const { full } = useDocsPage();

  return (
    <main className="contents">
      <article
        id="nd-page"
        data-full={full}
        {...props}
        className={cn(
          'flex flex-col w-full max-w-[900px] mx-auto [grid-area:main] px-4 py-6 gap-4 md:px-6 md:pt-8 xl:px-8 xl:pt-14',
          full && 'max-w-[1168px]',
          props.className,
        )}
      >
        {props.children}
      </article>
    </main>
  );
}
